    // .first(): Selenium By-locators resolve to the first match; the AUT even
    // ships duplicate ids, so keep that semantic instead of strict mode.
    this.heading = page.locator("#med-details-heading").first();
    this.drugName = page.locator("#med-name-result").first();
    this.doseInfo = page.locator("#med-detail-dfs").first();
    this.coverageContainer = page.locator("#detail-coverage-information").first();
    this.formularyStatusHeading = page.locator("#detail-coverage-information > h3:nth-of-type(1)").first();
